rss.channel:

{{ site.title | html.escape }}
{{ ref '/' }}
{{ site.description }}
lunet {{ lunet.version}}
{{ date.now | date.to_rfc822 | html.escape }}
{{ date.now | date.to_rfc822 | html.escape }}
{{~ $limit = page.rss_limit ?? site.rss.limit ?? 1000; ~}}
{{~ for post in site.pages.by_date.reverse ~}}
{{~ if post.layout_type != null && post.layout_type != 'single'; continue; end ~}}
{{~ if !(post.url | string.contains '/blog/'); continue; end ~}}
{{~ if (post.url | string.contains '/zh-cn/') || (post.url | string.contains '/es-us/') || (post.url | string.contains '/tr-tr/'); continue; end ~}}
  {{~ $limit = $limit - 1; if $limit < 0; break; end; ~}}


  {{ post.title | html.escape }}
  {{ ref post.url }}
  {{~ if post.date }}
  {{ post.date | date.to_rfc822 | html.escape }}
  {{~ end }}
  {{ ref post.url }}
  {{ post.summary | html.escape }}

{{~ end ~}}
